"""`mac mail` — generated by tools/gen_groups.py from local-mac's mail__* handlers. Do not edit."""
import argparse

from mac.groups._backend import call, given


def register(registry):
    def mail_read_args(p):
        p.add_argument('--folder', default=argparse.SUPPRESS)
        p.add_argument('--account', default=argparse.SUPPRESS)

    @registry.verb("mail", "read", mode="read",
                   desc="read recent emails from Apple Mail. account: 'gmail' (default), 'icloud', 'exchange', 'local' (On My Mac)", args=mail_read_args)
    def mail_read(ns):
        return call('mail', 'read', **given(ns, ('limit', 'folder', 'account')))

    def mail_get_args(p):
        p.add_argument('message_id', type=int)
        p.add_argument('--account', default=argparse.SUPPRESS)

    @registry.verb("mail", "get", mode="read",
                   desc="read full content of a specific email by message_id. account: 'gmail' (default), 'icloud', 'exchange'", args=mail_get_args)
    def mail_get(ns):
        return call('mail', 'get', **given(ns, ('message_id', 'account')))

    def mail_list_drafts_args(p):
        p.add_argument('--account', default=argparse.SUPPRESS)

    @registry.verb("mail", "list_drafts", mode="read",
                   desc="list draft emails from Apple Mail. account: 'gmail' (default), 'icloud', 'exchange', 'local' (On My Mac)", args=mail_list_drafts_args)
    def mail_list_drafts(ns):
        return call('mail', 'list_drafts', **given(ns, ('limit', 'account')))

    def mail_search_args(p):
        p.add_argument('query')
        p.add_argument('--folder', default=argparse.SUPPRESS)
        p.add_argument('--account', default=argparse.SUPPRESS)

    @registry.verb("mail", "search", mode="read",
                   desc="search emails by subject or sender. account: 'gmail' (default), 'icloud', 'exchange'", args=mail_search_args)
    def mail_search(ns):
        return call('mail', 'search', **given(ns, ('query', 'folder', 'limit', 'account')))

    def mail_list_mailboxes_args(p):
        p.add_argument('--account', default=argparse.SUPPRESS)

    @registry.verb("mail", "list_mailboxes", mode="read",
                   desc="list mailboxes for an account. account: 'gmail' (default), 'icloud', 'exchange', 'local' (On My Mac)", args=mail_list_mailboxes_args)
    def mail_list_mailboxes(ns):
        return call('mail', 'list_mailboxes', **given(ns, ('account',)))

    def mail_compose_args(p):
        p.add_argument('to')
        p.add_argument('--subject', default=argparse.SUPPRESS)
        p.add_argument('--body', default=argparse.SUPPRESS)

    @registry.verb("mail", "compose", mode="write",
                   desc='open a pre-filled compose window in Mail.app. Does not send — user reviews and sends manually', args=mail_compose_args)
    def mail_compose(ns):
        return call('mail', 'compose', **given(ns, ('to', 'subject', 'body')))

    def mail_delete_args(p):
        p.add_argument('message_ids', nargs="+", type=int)
        p.add_argument('--folder', default=argparse.SUPPRESS)
        p.add_argument('--account', default=argparse.SUPPRESS)

    @registry.verb("mail", "delete", mode="write",
                   desc="delete emails by message_id. Moves to Trash. account: 'gmail' (default), 'icloud', 'exchange', 'local' (On My Mac)", args=mail_delete_args)
    def mail_delete(ns):
        return call('mail', 'delete', **given(ns, ('message_ids', 'folder', 'account')))

    def mail_move_args(p):
        p.add_argument('message_ids', nargs="+", type=int)
        p.add_argument('dest_mailbox')
        p.add_argument('--src-account', default=argparse.SUPPRESS)
        p.add_argument('--src-folder', default=argparse.SUPPRESS)

    @registry.verb("mail", "move", mode="write",
                   desc='move emails from any internet account mailbox to an On My Mac local mailbox', args=mail_move_args)
    def mail_move(ns):
        return call('mail', 'move', **given(ns, ('message_ids', 'dest_mailbox', 'src_account', 'src_folder')))

    def mail_add_local_mailbox_args(p):
        p.add_argument('name')

    @registry.verb("mail", "add_local_mailbox", mode="write",
                   desc='create a new On My Mac mailbox in Mail.app and register it in LOCAL_MAILBOXES', args=mail_add_local_mailbox_args)
    def mail_add_local_mailbox(ns):
        return call('mail', 'add_local_mailbox', **given(ns, ('name',)))
